# Verify per-pair directions with correct key function
def f(g):
    h=len(g); w=len(g[0])
    best=None
    forms={'mr':lambda r,c:c-r,'ar':lambda r,c:c+r,'r':lambda r,c:r}
    for name,f in forms.items():
        L=defaultdict(set)
        for r in range(h):
            for c in range(w):
                if g[r][c]: L[f(r,c)].add(g[r][c])
        if not all(len(v)==1 for v in L.values()): continue
        ks=sorted(L.keys()); N=len(ks)
        # verify each key has single color AND keys distinct mod N
        good=all(len({L[x] for x in [k]})==1 for k in ks)
        pos={}
        ok=True
        for k,v in list(L.items()):
            i=(k-ks[0])%N
            c=list(v)[0]
            if i in pos and pos[i]!=c: ok=False; break
            pos[i]=c
        if not ok: continue
        out=[[pos[(f(r,c)-ks[0])%N] for c in range(w)] for r in range(h)]
        return out,name
    return None
for pair in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4','Demo pair 5']:
    o=G[pair+' output']
    s=n=f(G[pair+' input'])
    print(pair,n, 'match:', s==o)

