# Test the residue-mapping rule on every demo: N = #distinct stripe keys (nonzero), map key->color, then tile with period N using key % N. Check both directions (shift vs direct).
def f(g):
    h=len(g); w=len(g[0]); res=None
    for name,f in [('mr',lambda r,c:c-r),('ar',lambda r,c:c+r),('r',lambda r,c:r)]:
        L=defaultdict(set)
        for r in range(h):
            for c in range(w):
                if g[r][c]: L[f(r,c)].add(g[r][c])
        if not all(len(v)==1 for v in L.values()): continue
        ks=sorted(L.keys()); N=len(ks)
        bad=False; m={}
        for k,v in list(L.items()):
            i=k%N
            c=list(v)[0]
            if i in m and m[i]!=c: bad=True; break
            m[i]=c
        if bad: continue
        out=[[m[f(r,c)%N] for c in range(w)] for r in range(h)]
        res=(out,name)
    return res
