from collections import defaultdict
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(g):
    h=len(g); w=len(g[0]); best=None
    forms={'mr':lambda r,c:c-r,'ar':lambda r,c:c+r,'r':lambda r,c:r}
    for name,f in forms.items():
        L=defaultdict(set)
        for r in range(h):
            for c in range(w):
                if g[r][c]: L[f(r,c)].add(g[r][c])
        if not all(len(v)==1 for v in L.values()): continue
        ks=sorted(L.keys()); N=len(ks)
        m={}; ok=True
        base=ks[0]
        for k,v in list(L.items()):
            i=(k-base)%N
            c=list(v)[0]
            if i in m and m[i]!=c: ok=False; break
            m[i]=c
        if ok:
            out=[[m[(f(r,c)-base)%N] for c in range(w)] for r in range(h)]
            if best is None or True: best=(out,name)
    return best
